INSERT INTO questions (week, kind, topic, difficulty, prompt, answer, options, method)
SELECT week, kind, topic, difficulty, prompt, answer, options, method FROM seed s WHERE NOT EXISTS (
  SELECT 1 FROM questions q WHERE q.kind = s.kind AND q.week = s.week AND q.prompt = s.prompt AND q.worksheet_id IS NULL
);
